#!/usr/bin/env python3
"""Single-file offline preview of all 178 diagrams; intentionally no norm certification."""
import base64,json,html
from pathlib import Path
R=Path(__file__).resolve().parent.parent
J=json.loads((R/'quality-review.json').read_text(encoding='utf8'))['lessons']
D=[]
for r in J:
 content=(R/r['visual']).read_bytes()
 D.append({'id':r['id'],'title':r['title'],'course':r['course'],'mins':r['tts_minutes_estimate_130wpm'],
           'missing':r['missing_or_followup'],'src':'data:image/svg+xml;base64,'+base64.b64encode(content).decode('ascii')})
PAGE=r'''<!doctype html><html lang="de-CH"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Elektro EFZ – 178 Lernbilder und Qualitätsmatrix</title><style>
:root{font-family:system-ui,-apple-system,Segoe UI,sans-serif;color:#24384a;background:#e9f1f5}*{box-sizing:border-box}body{margin:0}header{background:#15354d;color:white;padding:25px max(18px,calc((100vw - 1260px)/2));}h1{font-size:clamp(23px,3vw,32px);margin:4px 0 10px}header p{color:#c6dfec;max-width:950px;line-height:1.5}main{display:grid;grid-template-columns:330px 1fr;gap:18px;max-width:1300px;margin:auto;padding:18px}.side{background:white;border-radius:14px;padding:14px;box-shadow:0 8px 24px #0d3e5b12;max-height:80vh;overflow:auto;position:sticky;top:16px}.side input,.side select{width:100%;padding:12px;border:1px solid #b8ceda;border-radius:9px;margin-bottom:9px;font-size:15px}.side button{display:block;width:100%;text-align:left;border:0;border-radius:9px;margin:4px 0;padding:10px;background:#f0f5f8;color:#1b445b;cursor:pointer;font:inherit}.side button.active{background:#1d6d87;color:white}.side button small{display:block;color:inherit;opacity:.77;font-size:11px}.panel{background:white;border-radius:14px;padding:clamp(15px,2vw,30px);box-shadow:0 8px 24px #0d3e5b12;min-width:0}.panel img{display:block;width:100%;height:auto;border:1px solid #d9e6ef;border-radius:12px}.panel h2{font-size:clamp(19px,2.6vw,27px)}.warning{background:#fff4de;color:#785024;border-radius:8px;padding:12px;line-height:1.5}.facts{display:flex;gap:9px;flex-wrap:wrap;margin:16px 0}.pill{border-radius:30px;background:#e7f0f4;padding:7px 11px;font-size:13px}.panel li{margin-bottom:6px}.nav{display:flex;justify-content:space-between;gap:15px;margin-top:17px}.nav button{border:0;background:#176c88;color:white;padding:12px 19px;border-radius:9px;cursor:pointer;font:inherit}.footer{color:#516d7d;line-height:1.5;font-size:13px;padding-top:10px}@media(max-width:780px){main{grid-template-columns:1fr}.side{position:static;max-height:230px}.panel{padding:14px}header{padding:20px}}
</style></head><body><header><h1>Elektro EFZ – Individuelle Lernbilder</h1><p>Offline-Vorschau: 178 thematisch angepasste SVG-Darstellungen und die Quellenlücken pro Lektion. Didaktische Visualisierungen, keine genehmigten Verdrahtungs- oder Installationspläne. Fachprüfung aller Grafiken und Normen weiterhin ausstehend.</p></header><main><aside class="side"><input id="search" type="search" placeholder="Lektion, Titel oder Thema suchen"><select id="year"><option value="">Alle Lektionen</option><option value="1.">1. Lehrjahr</option><option value="2.">2. Lehrjahr</option><option value="3.">3. Lehrjahr</option><option value="4.">4. Lehrjahr</option><option value="N-">Normen-Akademie</option></select><div id="list"></div></aside><section class="panel"><small id="eyebrow"></small><h2 id="title"></h2><img id="figure" alt="Individuelle Lernillustration"><div class="facts"><span class="pill" id="words"></span><span class="pill">Fachprüfung: offen</span><span class="pill">178 Abbildungen</span></div><h3>Quellenlücken und offene Prüfungen</h3><div class="warning">Keine gültige Normenfreigabe. Fehlende Detailquellen und unvollständige Norm-PDFs sind kein Ersatz für eine Prüfung am gültigen Original.</div><ul id="missing"></ul><div class="nav"><button id="prev">← Vorherige</button><button id="next">Nächste →</button></div><p class="footer">Die Manuskriptlänge ist nur eine Schätzung mit 130 Wörtern pro Minute. Eine volle fachliche Prüfung sowie die redaktionelle Langfassung aller 178 Lektionen ist nicht abgeschlossen.</p></section></main><script>
const DATA=@@DATA@@;let index=0,filtered=DATA;
const $=id=>document.getElementById(id);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function update(){const r=filtered[index]||DATA[0];if(!r)return;$('title').textContent=r.title;$('eyebrow').textContent='Lektion '+r.id+' · '+r.course;$('figure').src=r.src;$('figure').alt='Individuelle Illustration: '+r.title;$('words').textContent='Sprechertext ca. '+r.mins+' Min.';$('missing').innerHTML=(r.missing.length?r.missing:['Keine konkrete Dateilücke erkannt; Expertenprüfung trotzdem offen.']).map(x=>'<li>'+esc(x)+'</li>').join('');renderList()}
function renderList(){ $('list').innerHTML=filtered.map((r,i)=>'<button class="'+(i===index?'active':'')+'" data-i="'+i+'"><strong>'+esc(r.id)+'</strong> '+esc(r.title)+'<small>ca. '+r.mins+' Min. Audio-Text</small></button>').join('');$('list').querySelectorAll('button').forEach(b=>b.onclick=()=>{index=+b.dataset.i;update()});}
function filter(){let q=$('search').value.toLowerCase(),y=$('year').value;filtered=DATA.filter(r=>(!y||r.id.startsWith(y))&&[r.id,r.title,r.course].join(' ').toLowerCase().includes(q));index=0;update()}
$('search').oninput=filter;$('year').onchange=filter;$('prev').onclick=()=>{index=(index-1+filtered.length)%filtered.length;update()};$('next').onclick=()=>{index=(index+1)%filtered.length;update()};update();
</script></body></html>'''
page=PAGE.replace('@@DATA@@',json.dumps(D,ensure_ascii=False,separators=(',',':')))
p=R.parent/'Elektro_EFZ_v0.9.2_Alle_178_Lernbilder_Offline_Vorschau.html';p.write_text(page,encoding='utf8')
print(p, len(page)/1024/1024,'MB')
